const prisma = require('./src/lib/prisma')

async function main() {
  const users = await prisma.user.findMany({
    select: {
      name: true,
      email: true,
      role: true
    }
  })
  console.log('=== User List ===')
  console.log(JSON.stringify(users, null, 2))
}

main()
  .catch(console.error)
  .finally(() => prisma.$disconnect())

